--
-- Name: workflow_workflowinstance; Type: TABLE; Schema: public; Owner: logicon_user
--

CREATE TABLE public.workflow_workflowinstance (
    id bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    template_version integer NOT NULL,
    status character varying(16) NOT NULL,
    completed_at timestamp with time zone,
    initiated_by_id bigint NOT NULL,
    mrf_id bigint,
    org_id bigint NOT NULL,
    template_id bigint NOT NULL,
    client_onboarding_request_id bigint,
    approval_route_code_snapshot character varying(64) NOT NULL,
    approval_route_name_snapshot character varying(255) NOT NULL,
    approval_route_id bigint,
    proposal_version_id bigint,
    CONSTRAINT workflow_instance_exactly_one_target CHECK ((((client_onboarding_request_id IS NULL) AND (mrf_id IS NOT NULL) AND (proposal_version_id IS NULL)) OR ((client_onboarding_request_id IS NOT NULL) AND (mrf_id IS NULL) AND (proposal_version_id IS NULL)) OR ((client_onboarding_request_id IS NULL) AND (mrf_id IS NULL) AND (proposal_version_id IS NOT NULL)))),
    CONSTRAINT workflow_workflowinstance_template_version_check CHECK ((template_version >= 0))
);


ALTER TABLE public.workflow_workflowinstance OWNER TO logicon_user;

