    requires_comment_on_reject boolean NOT NULL,
    requires_comment_on_request_changes boolean NOT NULL,
    sla_hours integer,
    assigned_at timestamp with time zone,
    status character varying(16) NOT NULL,
    acted_at timestamp with time zone,
