    assigned_department_code_snapshot character varying(64) NOT NULL,
    assigned_department_name_snapshot character varying(128) NOT NULL,
    CONSTRAINT workflow_workflowstepinstance_sla_hours_check CHECK ((sla_hours >= 0)),
    CONSTRAINT workflow_workflowstepinstance_step_order_check CHECK ((step_order >= 0))
);


